arguments.new_str:
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers()
    .AddJsonOptions(options =>
    {
        options.JsonSerializerOptions.NumberHandling =
            System.Text.Json.Serialization.JsonNumberHandling.AllowNamedFloatingPointLiterals;
    });

builder.Services.AddSingleton<TicketModelService>();

var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");

// Train an initial model if one doesn't exist so PredictionEnginePool can load it
if (!File.Exists(modelPath))
{
    var mlService = new TicketModelService(builder.Environment.ContentRootPath);
    mlService.Train();
}

builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelPath, watchForChanges: true);

var app = builder.Build();
app.MapControllers();
app.Run();

